parameters.jsCode:
// Build fetch request
// Turns each due source row into the URL the "Fetch source" node calls.
// Google News and Hacker News sources only store a search query.
// Mode: Run Once for All Items.

const GN_LOCALE = {
  en: { hl: 'en-US', gl: 'US', ceid: 'US:en' },
  pl: { hl: 'pl', gl: 'PL', ceid: 'PL:pl' },
};
const qs = (o) => Object.entries(o)
  .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`)
  .join('&');
const dayAgo = Math.floor(Date.now() / 1000) - 86400;

return $input.all()
  .map((item, idx) => ({ s: item.json, idx }))
  .filter(({ s }) => s.id)
  .map(({ s, idx }) => {
    let url;
    if (s.source_type === 'google_news') {
      url = 'https://news.google.com/rss/search?'
        + qs({ q: `${s.query} when:1d`, ...(GN_LOCALE[s.lang] || GN_LOCALE.en) });
    } else if (s.source_type === 'hn_algolia') {
      url = 'https://hn.algolia.com/api/v1/search_by_date?'
        + qs({ query: s.query, tags: 'story', hitsPerPage: 50, numericFilters: `created_at_i>${dayAgo}` });
    } else {
      url = s.endpoint;
    }
    return {
      json: { source_id: s.id, source_name: s.name, source_type: s.source_type, fetch_url: url },
      pairedItem: { item: idx },
    };
  });

// Parse feed
// Normalises one HTTP response (RSS, Atom, Hacker News JSON, CISA KEV JSON)
// into [{url, title, summary, published_at}] for sp_record_fetch().
// Never throws: a failed source is passed on as `error`, so one dead feed
// cannot stop the run.
// Mode: Run Once for Each Item.

const src = $('Build fetch request').item.json;
const res = $json;
const MAX_ITEMS = 100;

const out = (items, error) => ({
  json: {
    source_id: src.source_id,
    source_name: src.source_name,
    items: items.slice(0, MAX_ITEMS),
    error: error ? String(error).slice(0, 500) : '',
  },
});

const decodeEntities = (s) => s
  .replace(/&#x([0-9a-f]+);/gi, (_, h) => String.fromCodePoint(parseInt(h, 16)))
  .replace(/&#(\d+);/g, (_, d) => String.fromCodePoint(Number(d)))
  .replace(/&nbsp;/g, ' ')
  .replace(/&quot;/g, '"')
  .replace(/&apos;/g, "'")
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&amp;/g, '&');

// CDATA -> entities -> tags -> entities again: Google News puts escaped
// HTML (with its own &nbsp;) in <description>.
const clean = (s) => decodeEntities(
  decodeEntities(String(s ?? '').replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1'))
    .replace(/<[^>]*>/g, ' '),
)
  .replace(/\s+/g, ' ')
  .trim();

const tag = (block, names) => {
  for (const name of names) {
    const m = block.match(new RegExp(`<${name}(?:\\s[^>]*)?>([\\s\\S]*?)</${name}>`, 'i'));
    if (m) return m[1];
  }
  return '';
};

const isoDate = (s) => {
  const d = new Date(clean(s));
  return Number.isNaN(d.getTime()) ? null : d.toISOString();
};

const atomLink = (block) => {
  const links = [...block.matchAll(/<link\b([^>]*)\/?>/gi)].map((m) => m[1]);
  const pick = links.find((a) => !/rel=["']/.test(a) || /rel=["']alternate["']/.test(a)) || links[0];
  const href = pick && pick.match(/href=["']([^"']+)["']/i);
  return href ? decodeEntities(href[1]) : '';
};

const parseXml = (xml) => {
  const rss = [...xml.matchAll(/<item\b[\s\S]*?<\/item>/gi)].map((m) => m[0]);
  if (rss.length) {
    return rss.map((b) => ({
      url: clean(tag(b, ['link'])) || clean(tag(b, ['guid'])),
      title: clean(tag(b, ['title'])),
      summary: clean(tag(b, ['description', 'content:encoded'])).slice(0, 2000),
      published_at: isoDate(tag(b, ['pubDate', 'dc:date', 'published', 'updated'])),
    }));
  }
  const atom = [...xml.matchAll(/<entry\b[\s\S]*?<\/entry>/gi)].map((m) => m[0]);
  return atom.map((b) => ({
    url: atomLink(b),
    title: clean(tag(b, ['title'])),
    summary: clean(tag(b, ['summary', 'content'])).slice(0, 2000),
    published_at: isoDate(tag(b, ['published', 'updated'])),
  }));
};

const parseHn = (data) => (data.hits || []).map((h) => ({
  url: h.url || `https://news.ycombinator.com/item?id=${h.objectID}`,
  title: h.title || '',
  summary: `Hacker News: ${h.points ?? 0} points, ${h.num_comments ?? 0} comments`,
  published_at: h.created_at || null,
}));

// KEV only has a date. Entries added today or yesterday (UTC) are new to us
// and get "now" as published_at, otherwise max_item_age_hours would mark
// yesterday's additions stale. URL dedupe stops them repeating.
const parseKev = (data) => {
  const cutoff = new Date(Date.now() - 86400000).toISOString().slice(0, 10);
  const now = new Date().toISOString();
  return (data.vulnerabilities || [])
    .filter((v) => v.dateAdded && v.dateAdded >= cutoff)
    .map((v) => ({
      url: `https://nvd.nist.gov/vuln/detail/${v.cveID}`,
      title: `${v.cveID}: ${v.vulnerabilityName} (${v.vendorProject} ${v.product}) added to CISA KEV`,
      summary: `${v.shortDescription || ''} Required action: ${v.requiredAction || ''}`.trim(),
      published_at: now,
    }));
};

if (res.error) return out([], res.error.message || JSON.stringify(res.error));
if (res.statusCode !== 200) return out([], `HTTP ${res.statusCode} ${res.statusMessage || ''}`.trim());

try {
  const body = res.body ?? res.data ?? '';
  const raw = typeof body === 'string' ? body : JSON.stringify(body);
  let items;
  if (src.source_type === 'hn_algolia') items = parseHn(typeof body === 'string' ? JSON.parse(raw) : body);
  else if (src.source_type === 'cisa_kev') items = parseKev(typeof body === 'string' ? JSON.parse(raw) : body);
  else items = parseXml(raw);
  items = items.filter((i) => /^https?:\/\//.test(i.url) && i.title);
  return out(items, null);
} catch (e) {
  return out([], `parse error: ${e.message}`);
}

// Build Gemini request
// One generateContent call for the whole claimed batch. The active prompt
// (prompts) gets the items in place of [[ITEMS_JSON]]; JSON mode +
// responseSchema make the answer machine-readable.
// Mode: Run Once for All Items.

const MODEL = 'gemini-3.1-flash-lite';

const rows = $input.all().map((i) => i.json).filter((r) => r.id);
if (!rows.length) return [];

const items = rows.map((r) => ({
  id: Number(r.id),
  source: r.source,
  title: r.title,
  summary: (r.summary || '').slice(0, 600),
  published_at: r.published_at,
  matched_keywords: r.matched_keywords,
}));

const prompt = rows[0].system_prompt.replace('[[ITEMS_JSON]]', JSON.stringify(items, null, 1));

const body = {
  contents: [{ role: 'user', parts: [{ text: prompt }] }],
  generationConfig: {
    temperature: 0.2,
    maxOutputTokens: 4096,
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'ARRAY',
      items: {
        type: 'OBJECT',
        properties: {
          id: { type: 'INTEGER' },
          score: { type: 'INTEGER' },
          summary_pl: { type: 'STRING' },
          reason: { type: 'STRING' },
        },
        required: ['id', 'score', 'summary_pl', 'reason'],
      },
    },
  },
};

return [{
  json: { model: MODEL, prompt_version: rows[0].prompt_version, ids: items.map((i) => i.id), body },
}];

// Parse verdicts
// Keeps only well-formed verdicts for ids that were actually claimed.
// On any error nothing is stored: the items stay pending_ai and are
// retried; after ai_max_attempts housekeeping marks them ai_error.
// Mode: Run Once for All Items.

const req = $('Build Gemini request').first().json;
const res = $input.first().json;

let verdicts = [];
let error = '';

if (res.error) {
  error = `Gemini request failed: ${res.error.message || JSON.stringify(res.error)}`;
} else if (res.statusCode !== 200) {
  error = `Gemini HTTP ${res.statusCode}: ${res.body?.error?.message || res.statusMessage || ''}`;
} else {
  try {
    const parts = res.body?.candidates?.[0]?.content?.parts || [];
    const parsed = JSON.parse(parts.map((p) => p.text || '').join(''));
    const claimed = new Set(req.ids);
    verdicts = (Array.isArray(parsed) ? parsed : [])
      .map((v) => ({
        id: Number(v.id),
        score: Math.round(Number(v.score)),
        summary_pl: String(v.summary_pl ?? '').slice(0, 1000),
        reason: String(v.reason ?? '').slice(0, 500),
      }))
      .filter((v) => claimed.has(v.id) && v.score >= 1 && v.score <= 5);
  } catch (e) {
    error = `Cannot parse Gemini answer: ${e.message}`;
  }
}

return [{
  json: {
    verdicts,
    model: req.model,
    prompt_version: req.prompt_version,
    claimed: req.ids.length,
    error,
  },
}];

parameters.query:
-- score >= digest_min_ai_score => alert (next digest), else scored.
SELECT news.sp_store_verdicts($1::jsonb, $2, $3) AS stored,
       $4::int AS claimed, NULLIF($5, '') AS error;

parameters.jsCode:
// Build digest e-mail
// Input: rows of "Digest due?" — nothing when no slot is due, one row with
// only digest_id when the slot is due but nothing qualifies, otherwise one
// row per item. Every dynamic value is HTML-escaped (titles and summaries
// come from the internet).
// Mode: Run Once for All Items.

const rows = $input.all().map((i) => i.json).filter((r) => r.digest_id);
if (!rows.length) return [];

const digestId = rows[0].digest_id;
const items = rows.filter((r) => r.id);
if (!items.length) {
  return [{ json: { digest_id: digestId, empty: true, ids: '{}' } }];
}

const esc = (v) => String(v ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const safeUrl = (u) => (/^https?:\/\//i.test(u || '') ? esc(u) : '#');
const local = (ts) => DateTime.fromISO(new Date(ts).toISOString()).setZone('Europe/Warsaw');

const SCORE_COLOR = { 5: '#f44336', 4: '#ff9800', 3: '#ffc107', 2: '#90a4ae', 1: '#607d8b' };
const TOPICS = [
  ['cyber', '🛡️ Cyber'],
  ['ai', '🤖 AI'],
  ['both', '📌 Other'],
];

const card = (r) => {
  const score = r.ai_score ?? '–';
  const color = SCORE_COLOR[r.ai_score] || '#607d8b';
  const summary = r.ai_summary_pl || '';
  return `
  <div style="border-left:4px solid ${color};background:#252525;border-radius:4px;padding:10px 12px;margin:0 0 10px;">
    <div style="font-size:15px;line-height:1.4;">
      <span style="display:inline-block;min-width:22px;text-align:center;background:${color};color:#111;font-weight:700;border-radius:3px;padding:0 5px;margin-right:6px;">${esc(score)}</span>
      <a href="${safeUrl(r.url)}" style="color:#90caf9;text-decoration:none;">${esc(r.title)}</a>
    </div>
    ${summary ? `<div style="margin-top:6px;font-size:14px;line-height:1.5;color:#e0e0e0;">${esc(summary)}</div>` : ''}
    <div style="margin-top:6px;font-size:12px;color:#888;">${esc(r.source || '')} · ${esc(local(r.published_at).toFormat('dd.MM HH:mm'))}</div>
  </div>`;
};

const sections = TOPICS
  .map(([topic, label]) => {
    const list = items.filter((r) => (r.topic || 'both') === topic);
    if (!list.length) return '';
    return `<h3 style="margin:18px 0 8px;color:#bbb;font-size:14px;text-transform:uppercase;letter-spacing:.05em;">${label} (${list.length})</h3>${list.map(card).join('')}`;
  })
  .join('');

const now = DateTime.now().setZone('Europe/Warsaw');
const top = Math.max(...items.map((r) => Number(r.ai_score) || 0));
const subject = `📰 News Radar ${now.toFormat('HH:mm')} — ${items.length} ${items.length === 1 ? 'news' : 'newsów'}`
  + (top >= 5 ? ' (jest coś pilnego)' : '');

const html = `<!DOCTYPE html>
<html><body style="font-family:'Segoe UI',Tahoma,sans-serif;background:#121212;color:#e0e0e0;margin:0;padding:20px;">
<div style="max-width:680px;margin:auto;background:#1e1e1e;border:1px solid #333;border-top:4px solid #3fb68b;border-radius:8px;overflow:hidden;">
  <div style="background:#1b3320;padding:14px;text-align:center;">
    <h2 style="margin:0;color:#81c784;">Sentinel Codex · News Radar</h2>
    <div style="color:#9e9e9e;font-size:13px;margin-top:4px;">${esc(now.toFormat('dd.MM.yyyy HH:mm'))} · ${items.length} pozycji, od najważniejszych</div>
  </div>
  <div style="padding:18px 22px;">${sections}</div>
  <div style="padding:10px 22px 16px;color:#777;font-size:11px;">Ocena 1–5 i streszczenia: Gemini. Źródła, słowa kluczowe i godziny wysyłki: strona Sentinel Codex · News Radar.</div>
</div>
</body></html>`;

return [{
  json: {
    digest_id: digestId,
    empty: false,
    ids: `{${items.map((r) => r.id).join(',')}}`,
    subject,
    html,
  },
}];
